contract InvMutTest {
    C c;
    bool didRevert;

    constructor(C _c) {
        c = _c;
    }

    function test(bytes32 hash, uint256 value) public {
        require(value != 1 ether);
        uint256 balBefore = address(c).balance;
        didRevert = false;
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));
        if (!success) {
            didRevert = true;
        }
        uint256 balAfter = address(c).balance;
        assert(didRevert || (balAfter == balBefore + 1 ether));
    }
}

