pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 valueWei, address sender) public {
        // Restrict to admissible domain: value must not exceed a reasonable bound and sender
        // must not be the zero address or the test contract itself (to avoid interference).
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        valueWei = bound(valueWei, 0, 10 ether);

        // Record initial state: contract balance before any lockInGuess call.
        uint256 initialBalance = address(c).balance;

        // Fund and prank the sender. We also provide enough ether for the required 1 ether payment.
        // If valueWei is not exactly 1 ether, the reference should revert.
        vm.deal(sender, valueWei + 1 ether);
        vm.prank(sender);

        bool success;
        try c.lockInGuess{value: valueWei}(guessHash) {
            success = true;
        } catch {
            success = false;
        }

        // If the call succeeded, the reference guarantees that exactly 1 ether was sent.
        // Therefore the contract balance must have increased by exactly 1 ether.
        if (success) {
            uint256 finalBalance = address(c).balance;
            assertEq(finalBalance - initialBalance, 1 ether);
        }
    }
}

