import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, bytes32 guess1, bytes32 guess2) public {
        // Ensure valid guesses: distinct values to make overwrite detectable
        vm.assume(guess1 != guess2);
        // Ensure actor is not the zero address and distinct from the test contract
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Fund actor with enough Ether for two calls (2 ether)
        vm.deal(actor, 2 ether);

        // First call: lock in guess1
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess1);

        // Record the block number returned after first call
        // Because guesses is private, we cannot read guesses[actor].block directly.
        // But the property we care about is the lock block of the *last* successful lockInGuess.
        // We use a derived observation: after the second call, the contract balance should reflect the correct state.
        // Rule: After a second lockInGuess (overwrite), the guess is updated, but the block should also be updated in correct C.
        // In mutant, block is also updated, so difference is not about block value.
        // Difference is about balance: mutant allows overwrite without paying, but we pay here anyway, so balance remains consistent.
        // The actual semantic difference: in correct C, a second call with 1 ether succeeds and updates both guess and block.
        // In mutant, a second call with 1 ether also succeeds and updates both guess and block.
        // The mutation only removes the require(guesses[msg.sender].block == 0), which checks if a guess is already active.
        // In correct C, calling lockInGuess while a guess is pending (block > 0) will revert.
        // In mutant, it succeeds and overwrites.
        // Therefore, the property is: calling lockInGuess *twice* with 1 ether each should succeed in mutant, but should revert in correct C on the second call.

        // We need to observe a revert on second call in correct C. Let's test that directly.
        // The only way to observe this is via try/catch around the second call.
        // If correct C reverts, ok = false; if mutant succeeds, ok = true.
        // We want the rule: "second lockInGuess call always reverts" (correct C), which mutant violates.
        // But the problem says "State a general rule that the reference satisfies for EVERY input, and that the bug breaks for at least some input."
        // And "Take the deciding values as fuzz parameters". The deciding value is the actor and the two hashes.
        // So we fuzz them and assert that the second call reverts.

        // Perform second call and catch revert
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(guess2) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C should revert on second call, so ok must be false.
        // The mutant should succeed, so ok becomes true, breaking the rule.
        assertTrue(!ok, "Second lockInGuess should revert while guess pending");
    }
}

