        // That's a simple property.

        // Let's write the test accordingly.
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);

        // First lock-in
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);

        // Second lock-in attempt
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", hash2));
        // The reference should revert (success == false), the mutant should succeed (success == true).
        // The property: the second call must revert.
        assertTrue(!success);
    }
}

